<div class="page-head"><div><h1><?= $archived ? 'Archived documents' : 'Documents' ?></h1><div class="sub">Every file is stored privately and can only be opened by signed-in staff with permission.</div></div>
  <?php if (can('documents.delete')): ?><a class="btn btn-light border" href="<?= e(url('documents', $archived ? [] : ['status' => 'archived'])) ?>"><i class="bi bi-archive me-1"></i><?= $archived ? 'Active documents' : 'Archived' ?></a><?php endif; ?></div>
<div class="card">
  <div class="card-body border-bottom"><form class="row g-2" method="get"><input type="hidden" name="r" value="documents"><?php if ($archived): ?><input type="hidden" name="status" value="archived"><?php endif; ?>
    <div class="col-md-5"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Search title, file name or category"></div>
    <div class="col-md-3"><select class="form-select" name="type" data-autosubmit><option value="">All records</option><?php if (in_array('customer', $allowed, true)): ?><option value="customer"<?= selected($type, 'customer') ?>>People</option><?php endif; ?><?php if (in_array('property', $allowed, true)): ?><option value="property"<?= selected($type, 'property') ?>>Properties</option><?php endif; ?><?php if (in_array('tenancy', $allowed, true)): ?><option value="tenancy"<?= selected($type, 'tenancy') ?>>Tenancies</option><?php endif; ?><?php if (in_array('sale', $allowed, true)): ?><option value="sale"<?= selected($type, 'sale') ?>>Sales</option><?php endif; ?><?php if (in_array('plot', $allowed, true)): ?><option value="plot"<?= selected($type, 'plot') ?>>Land plots</option><?php endif; ?></select></div>
    <div class="col-md-2"><select class="form-select" name="category" data-autosubmit><option value="">All categories</option><?php foreach ($cats as $c): ?><option<?= selected($cat, $c) ?>><?= e($c) ?></option><?php endforeach; ?></select></div>
    <div class="col-md-2 d-flex gap-2"><button class="btn btn-primary flex-fill">Search</button></div></form></div>
  <?php if (!$rows): ?><div class="empty"><i class="bi bi-folder2-open"></i>No documents found. Upload documents from a person's or property's page.</div>
  <?php else: ?>
  <div class="table-responsive"><table class="table table-hover table-stack align-middle"><thead><tr><th>Document</th><th>Attached to</th><th>Category</th><th>Size</th><th>Uploaded</th><th></th></tr></thead><tbody>
  <?php foreach ($rows as $d): $isImg = str_starts_with($d['mime_type'], 'image/'); $isPdf = $d['mime_type'] === 'application/pdf'; ?>
    <tr><td class="cell-main"><i class="bi <?= $isPdf ? 'bi-file-earmark-pdf text-danger' : ($isImg ? 'bi-file-earmark-image text-primary' : 'bi-file-earmark-text text-secondary') ?> me-2"></i><?= e($d['title']) ?><div class="small text-muted"><?= e($d['original_name']) ?></div></td>
      <td data-label="Attached to"><a href="<?= e(['property' => url('properties/view', ['id' => $d['owner_id']]), 'tenancy' => url('tenancies/view', ['id' => $d['owner_id']]), 'sale' => url('sales/view', ['id' => $d['owner_id']]), 'plot' => url('land/view', ['id' => $d['owner_id']])][$d['owner_type']] ?? url('customers/view', ['id' => $d['owner_id']])) ?>"><?= e(str_limit($d['owner_label'] ?? 'Record', 40)) ?></a><div class="small text-muted"><?= ['property' => 'Property', 'tenancy' => 'Tenancy', 'sale' => 'Sale', 'plot' => 'Plot'][$d['owner_type']] ?? 'Person' ?><?= $d['context'] ? ' · ' . e(ucfirst($d['context'])) : '' ?></div></td>
      <td data-label="Category"><?= e($d['category']) ?></td><td data-label="Size"><?= e(fmt_bytes((int)$d['file_size'])) ?></td>
      <td data-label="Uploaded"><?= e(fmt_date($d['created_at'])) ?><div class="small text-muted"><?= e($d['uploader'] ?? '') ?></div></td>
      <td class="cell-actions text-end text-nowrap"><?php if ($isPdf || $isImg): ?><a class="btn btn-sm btn-light" target="_blank" rel="noopener" href="<?= e(url('documents/download', ['id' => $d['id'], 'inline' => 1])) ?>"><i class="bi bi-eye"></i></a><?php endif; ?>
        <a class="btn btn-sm btn-light" href="<?= e(url('documents/download', ['id' => $d['id']])) ?>"><i class="bi bi-download"></i></a>
        <?php if ($archived && can('documents.delete')): ?><form method="post" action="<?= e(url('documents/restore')) ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$d['id'] ?>"><button class="btn btn-sm btn-light text-success" title="Restore"><i class="bi bi-arrow-counterclockwise"></i></button></form><?php endif; ?></td></tr>
  <?php endforeach; ?></tbody></table></div><?php View::partial('pager', ['pg' => $pg]); endif; ?>
</div>
